<?php declare(strict_types=1);
function ownJournalScope(array$f):array{$clubs=array_values($f['data']['profile_clubs']??[]);if(count($clubs)!==8)throw new RuntimeException('Eight actual journal clubs required');foreach($clubs as$i=>$club)if($club!=='own-journal-ui-'.($i+1))throw new RuntimeException('Exact original journal club required');return$clubs;}
function ownJournalFilter(array$clubs):callable{return static fn(string$table):array=>in_array($table,['balance_periods','balance_period_events','audit_events'],true)?[' WHERE club_id NOT IN('.implode(',',array_fill(0,count($clubs),'?')).')',$clubs]:['',[]];}
function ownJournalRows(PDO$db,string$table,array$clubs):array{
 if(!in_array($table,['balance_periods','balance_period_events','audit_events'],true))throw new RuntimeException('Exact original journal table required');$q=$db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$columns=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION");$q->execute([$table]);$primary=$q->fetchAll(PDO::FETCH_COLUMN);if(!$columns||!$primary)throw new RuntimeException('Actual journal columns and primary keys required');$quote=static fn(string$v):string=>'`'.str_replace('`','``',$v).'`';$q=$db->prepare('SELECT '.implode(',',array_map($quote,$columns)).' FROM '.$quote($table).' WHERE club_id IN('.implode(',',array_fill(0,count($clubs),'?')).') ORDER BY '.implode(',',array_map($quote,$primary)));$q->execute($clubs);return$q->fetchAll(PDO::FETCH_ASSOC);
}
function ownBalancePeriodJournalProof(array$f):void{
 $c=Kulturhus\Native\TestSupport::config();$profile=$_SERVER['HTTP_X_OWNED_JOURNAL_PROFILE']??null;
 if(PHP_SAPI!=='cli-server'||($_SERVER['REQUEST_METHOD']??'')!=='GET'||($c['owner']??'')!=='isolated-native-ci'||($c['label']??'')!=='native-balance-period-journal-interface'||($c['host']??'')!=='127.0.0.1'||($c['port']??0)!==13371||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',$c['database']??'')||!is_string($profile)||!preg_match('/\A[1-8]\z/D',$profile)||!is_string($_SERVER['HTTP_X_OWNED_PERIOD_JOURNAL_PROOF']??null)||!hash_equals($f['data']['proof_nonce']??'',$_SERVER['HTTP_X_OWNED_PERIOD_JOURNAL_PROOF'])){http_response_code(403);exit;}
 require_once dirname(__DIR__,2).'/src/autoload.php';require_once __DIR__.'/original-database-hash.php';$db=Kulturhus\Native\TestSupport::db();if($db->query('SELECT DATABASE()')->fetchColumn()!==$c['database']||(int)$db->query('SELECT MAX(version)FROM schema_migrations')->fetchColumn()!==135){http_response_code(403);exit;}
 $clubs=ownJournalScope($f);$tables=array_values(array_diff($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN),['native_auth_sessions','native_auth_limits','native_language_preferences']));$service=new Kulturhus\Verein\BalancePeriodLedger($db,'jrn-'.$profile.'-finance');$periods=$service->periods();$state=$periods?$service->report($f['data']['period_id']):null;
 header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');echo json_encode(['protected_sha256'=>ownOriginalDatabaseHash($db,$tables,ownJournalFilter($clubs)),'protected_tables'=>count($tables),'definitions'=>ownJournalRows($db,'balance_periods',$clubs),'records'=>ownJournalRows($db,'balance_period_events',$clubs),'audits'=>ownJournalRows($db,'audit_events',$clubs),'state'=>$state,'profile'=>(int)$profile],JSON_THROW_ON_ERROR),PHP_EOL;
